set-variable.value:
#[output application/java --- {
	'x-correlation-id': correlationId,
	'x-client-app': attributes.headers.client_id default 'unknown-client',
	('Idempotency-Key': attributes.headers.'idempotency-key') if (attributes.headers.'idempotency-key' != null)
}]

#[output application/java --- {
	('Retry-After': attributes.headers.'retry-after') if (attributes.headers.'retry-after' != null),
	(Location: p('http.listener.basePath') ++ '/order-requests/' ++ payload.requestId) if (attributes.statusCode == 202 and payload.requestId != null)
}]
